ee:variables.ee:set-variable:
%dw 2.0
output application/json

// Helper function to handle the math and rounding
fun convert(val: Number) = 
    round(val / 42 * 10) / 10

---
{
    InventoryDate: vars.tempTms6Data.InventoryDate,
    products: vars.tempTms6Data.products map (item) -> {
        tank: item.tank,
        productName: item.productName,
        // We take the FIRST volume/stockAdjust found and convert it
        volume: convert(item.volume),
        stockAdjust: convert(item.stockAdjust)
    },
    StockHolders: vars.tempTms6Data.StockHolders mapObject (products, holder) -> {
        (holder): products map (item) -> {
            tank: item.tank,
            productName: item.productName,
            volume: convert(item.volume),
            stockAdjust: convert(item.stockAdjust)
        }
    }
}

%dw 2.0 output application/json
var columnCount = if (vars.flag == "update") vars.existInvColIndex else vars.inventoryOrBreakoutColumnCount var nextColumnCount = columnCount + 1 var preColumnCount = columnCount - 1 var letters = "ABCDEFGHIJKLMNOPQRSTUVWXYZ"
fun toExcelColumn(n) = if (n <= 0) "" else do { var rem = (n - 1) mod 26 var quotient = floor((n - 1) / 26) --- toExcelColumn(quotient) ++ (letters[rem to rem]) }
--- { Number: columnCount, CurrentColumn: toExcelColumn(columnCount), NextColumn: toExcelColumn(nextColumnCount), PreviousColumn: toExcelColumn(preColumnCount) }

%dw 2.0
output application/json
---
if(payload== p('inventory.sheetName')) ("A1:B" ++ (vars."previousInventoryRowCount" + 1))
else if(payload == p('mtd.sheetName')) ("A1:I" ++ (vars."previousInventoryRowCount" + 1))
else if(payload == p('tis.sheetName')) ("A1:B" ++ (vars."previousInventoryRowCount" + 1))
else if (payload == p('tms6.sheetName')) ("A1:B" ++ (vars."previousInventoryRowCount" + 1))
else if(payload == p('freepointBreakout.sheetName')) ("A1:B" ++ (vars."previousInventoryRowCount" + 1))
else "no sheet found"

ee:message.ee:set-payload:
%dw 2.0
output application/json
---
{
  message: {
    subject: "Inventory and Rack Reports Processed Successfully",
    body: {
      contentType: "HTML",
      content: 
        "<p>Hi Team,</p>" ++
        "<p>This is to inform you that the <b>Inventory and Rack Reports</b> has been processed successfully by the MuleSoft Automation.</p>" ++
        "<table border='1' cellpadding='5' cellspacing='0' style='border-collapse: collapse;'>" ++
          "<tr><th>Field</th><th>Value</th></tr>" ++
          "<tr><td>Inventory Date</td><td>" ++ (vars.checkDocNames.date[0] default "") ++ "</td></tr>" ++
          "<tr><td>Email Received DateTime</td><td>" ++ (vars.vReceivedDatetime default "-") ++ "</td></tr>" ++
          "<tr><td>Status</td><td>Success</td></tr>" ++
          "<tr><td>Document Name</td><td>" ++ ((vars.allPDFs default []) map ($ as String) joinBy "<br>") ++ "</td></tr>" ++
          "<tr><td>Timestamp (UTC)</td><td>" ++ (now() >> "UTC") ++ "</td></tr>" ++
        "</table>" ++
        "<p>The automation process completed without any errors.</p>" ++
        "<p>Thank you</p>"
    },
    toRecipients: (p('mail.to') splitBy ",") map (email) -> {
      emailAddress: {
        address: trim(email)
      }
    },
    ccRecipients: (p('mail.cc') splitBy ",") map (email) -> {
      emailAddress: {
        address: trim(email)
      }
    }
  },
  saveToSentItems: false
}
